59	    // because any fully acked page will be removed from this list potentially creating pageNum gaps in the list.
60	    protected final List<Page> tailPages;
61	
62	    // this list serves the only purpose of quickly retrieving the first unread page, operation necessary on every read
63	    // reads will simply remove the first page from the list when fully read and writes will append new pages upon beheading
64	    protected final List<Page> unreadTailPages;
