93	    public Queue(Settings settings) {
94	        try {
95	            final Path queueDir = Paths.get(settings.getDirPath());
96	            Files.createDirectories(queueDir);
97	            this.dirPath = queueDir.toRealPath();
98	        } catch (final IOException ex) {
99	            throw new IllegalStateException(ex);
100	        }
101	        this.pageCapacity = settings.getCapacity();
102	        this.maxBytes = settings.getQueueMaxBytes();
103	        this.checkpointIO = new FileCheckpointIO(dirPath, settings.getCheckpointRetry());
104	        this.elementClass = settings.getElementClass();
105	        this.tailPages = new ArrayList<>();
106	        this.unreadTailPages = new ArrayList<>();
107	        this.closed = new AtomicBoolean(true); // not yet opened
108	        this.maxUnread = settings.getMaxUnread();
109	        this.checkpointMaxAcks = settings.getCheckpointMaxAcks();
110	        this.checkpointMaxWrites = settings.getCheckpointMaxWrites();
111	        this.unreadCount = 0L;
112	
113	        // retrieve the deserialize method
114	        try {
115	            final Class<?>[] cArg = new Class<?>[1];
116	            cArg[0] = byte[].class;
117	            this.deserializeMethod = this.elementClass.getDeclaredMethod("deserialize", cArg);
118	        } catch (NoSuchMethodException e) {
119	            throw new QueueRuntimeException("cannot find deserialize method on class " + this.elementClass.getName(), e);
120	        }
