135	    public long getPersistedByteSize() {
136	        lock.lock();
137	        try {
138	            final long size;
139	            if (headPage == null) {
140	                size = 0L;
141	            } else {
142	                size = headPage.getPageIO().getHead()
143	                    + tailPages.stream().mapToLong(p -> p.getPageIO().getHead()).sum();
144	            }
145	            return size;
146	        } finally {
147	            lock.unlock();
148	        }
149	    }
