159	    /**
160	     * Open an existing {@link Queue} or create a new one in the configured path.
161	     * @throws IOException if an IO error occurs
162	     */
163	    public void open() throws IOException {
164	        if (!this.closed.get()) { throw new IOException("queue already opened"); }
165	
166	        lock.lock();
167	        try {
168	            try {
169	                // verify exclusive access to the dirPath
170	                this.dirLock = FileLockFactory.obtainLock(this.dirPath, LOCK_NAME);
171	            } catch (LockException e) {
172	                throw new LockException("The queue failed to obtain exclusive access, cause: " + e.getMessage());
173	            }
174	
175	            try {
176	                openPages();
177	                this.closed.set(false);
178	            } catch (IOException e) {
179	                // upon any exception while opening the queue and after dirlock has been obtained
180	                // we need to make sure to release the dirlock. Calling the close method on a partially
181	                // open queue has no effect because the closed flag is still true.
182	                releaseLockAndSwallow();
183	                throw(e);
184	            }
185	        } finally {
186	            lock.unlock();
187	        }
188	    }
