190	    private void openPages() throws IOException {
191	        final int headPageNum;
192	
193	        // Upgrade to serialization format V2
194	        QueueUpgrade.upgradeQueueDirectoryToV2(dirPath);
195	
196	        Checkpoint headCheckpoint;
197	        try {
198	            headCheckpoint = this.checkpointIO.read(checkpointIO.headFileName());
199	        } catch (NoSuchFileException e) {
200	            // if there is no head checkpoint, create a new headpage and checkpoint it and exit method
201	
202	            logger.debug("No head checkpoint found at: {}, creating new head page", checkpointIO.headFileName());
203	
204	            this.ensureDiskAvailable(this.maxBytes, 0);
205	
206	            this.seqNum = 0;
207	            headPageNum = 0;
208	
209	            newCheckpointedHeadpage(headPageNum);
210	            this.closed.set(false);
211	
212	            return;
213	        }
214	
215	        // at this point we have a head checkpoint to figure queue recovery
216	
217	        // as we load pages, compute actually disk needed substracting existing pages size to the required maxBytes
218	        long pqSizeBytes = 0;
219	
220	        // reconstruct all tail pages state upto but excluding the head page
221	        for (int pageNum = headCheckpoint.getFirstUnackedPageNum(); pageNum < headCheckpoint.getPageNum(); pageNum++) {
222	            final String cpFileName = checkpointIO.tailFileName(pageNum);
223	            if (!dirPath.resolve(cpFileName).toFile().exists()) {
224	                continue;
225	            }
226	            final Checkpoint cp = this.checkpointIO.read(cpFileName);
227	
228	            logger.debug("opening tail page: {}, in: {}, with checkpoint: {}", pageNum, this.dirPath, cp.toString());
229	
230	            PageIO pageIO = new MmapPageIOV2(pageNum, this.pageCapacity, this.dirPath);
231	            // important to NOT pageIO.open() just yet, we must first verify if it is fully acked in which case
232	            // we can purge it and we don't care about its integrity for example if it is of zero-byte file size.
233	            if (cp.isFullyAcked()) {
234	                purgeTailPage(cp, pageIO);
235	            } else {
236	                pageIO.open(cp.getMinSeqNum(), cp.getElementCount());
237	                addTailPage(PageFactory.newTailPage(cp, this, pageIO));
238	                pqSizeBytes += pageIO.getCapacity();
239	            }
240	
241	            // track the seqNum as we rebuild tail pages, prevent empty pages with a minSeqNum of 0 to reset seqNum
242	            if (cp.maxSeqNum() > this.seqNum) {
243	                this.seqNum = cp.maxSeqNum();
244	            }
245	        }
246	
247	        // delete zero byte page and recreate checkpoint if corrupted page is detected
248	        if ( cleanedUpFullyAckedCorruptedPage(headCheckpoint, pqSizeBytes)) { return; }
249	
250	        // transform the head page into a tail page only if the headpage is non-empty
251	        // in both cases it will be checkpointed to track any changes in the firstUnackedPageNum when reconstructing the tail pages
252	
253	        logger.debug("opening head page: {}, in: {}, with checkpoint: {}", headCheckpoint.getPageNum(), this.dirPath, headCheckpoint.toString());
254	
255	        PageIO pageIO = new MmapPageIOV2(headCheckpoint.getPageNum(), this.pageCapacity, this.dirPath);
256	        pageIO.recover(); // optimistically recovers the head page data file and set minSeqNum and elementCount to the actual read/recovered data
257	
258	        pqSizeBytes += (long) pageIO.getHead();
259	        ensureDiskAvailable(this.maxBytes, pqSizeBytes);
260	
261	        if (pageIO.getMinSeqNum() != headCheckpoint.getMinSeqNum() || pageIO.getElementCount() != headCheckpoint.getElementCount()) {
262	            // the recovered page IO shows different minSeqNum or elementCount than the checkpoint, use the page IO attributes
263	
264	            logger.warn("recovered head data page {} is different than checkpoint, using recovered page information", headCheckpoint.getPageNum());
265	            logger.debug("head checkpoint minSeqNum={} or elementCount={} is different than head pageIO minSeqNum={} or elementCount={}", headCheckpoint.getMinSeqNum(), headCheckpoint.getElementCount(), pageIO.getMinSeqNum(), pageIO.getElementCount());
266	
267	            long firstUnackedSeqNum = headCheckpoint.getFirstUnackedSeqNum();
268	            if (firstUnackedSeqNum < pageIO.getMinSeqNum()) {
269	                logger.debug("head checkpoint firstUnackedSeqNum={} is < head pageIO minSeqNum={}, using pageIO minSeqNum", firstUnackedSeqNum, pageIO.getMinSeqNum());
270	                firstUnackedSeqNum = pageIO.getMinSeqNum();
271	            }
272	            headCheckpoint = new Checkpoint(headCheckpoint.getPageNum(), headCheckpoint.getFirstUnackedPageNum(), firstUnackedSeqNum, pageIO.getMinSeqNum(), pageIO.getElementCount());
273	        }
274	        this.headPage = PageFactory.newHeadPage(headCheckpoint, this, pageIO);
275	
276	        if (this.headPage.getMinSeqNum() <= 0 && this.headPage.getElementCount() <= 0) {
277	            // head page is empty, let's keep it as-is
278	            // but checkpoint it to update the firstUnackedPageNum if it changed
279	            this.headPage.checkpoint();
280	        } else {
281	            // head page is non-empty, transform it into a tail page
282	            this.headPage.behead();
283	
284	            if (headCheckpoint.isFullyAcked()) {
285	                purgeTailPage(headCheckpoint, pageIO);
286	            } else {
287	                addTailPage(this.headPage);
288	            }
289	
290	            // track the seqNum as we add this new tail page, prevent empty tailPage with a minSeqNum of 0 to reset seqNum
291	            if (headCheckpoint.maxSeqNum() > this.seqNum) {
292	                this.seqNum = headCheckpoint.maxSeqNum();
293	            }
294	
295	            // create a new empty head page
296	            headPageNum = headCheckpoint.getPageNum() + 1;
297	            newCheckpointedHeadpage(headPageNum);
298	        }
299	
300	        // only activate the first tail page
301	        if (tailPages.size() > 0) {
302	            this.tailPages.get(0).getPageIO().activate();
303	        }
304	
305	        // TODO: here do directory traversal and cleanup lingering pages? could be a background operations to not delay queue start?
306	    }
