308	    /**
309	     * When the queue is fully acked and zero byte page is found, delete corrupted page and recreate checkpoint head
310	     * @param headCheckpoint
311	     * @param pqSizeBytes
312	     * @return true when corrupted page is found and cleaned
313	     * @throws IOException
314	     */
315	    private boolean cleanedUpFullyAckedCorruptedPage(Checkpoint headCheckpoint, long pqSizeBytes) throws IOException {
316	        if (headCheckpoint.isFullyAcked()) {
317	            PageIO pageIO = new MmapPageIOV2(headCheckpoint.getPageNum(), this.pageCapacity, this.dirPath);
318	            if (pageIO.isCorruptedPage()) {
319	                logger.debug("Queue is fully acked. Found zero byte page.{}. Recreate checkpoint.head and delete corrupted page", headCheckpoint.getPageNum());
320	
321	                this.checkpointIO.purge(checkpointIO.headFileName());
322	                pageIO.purge();
323	
324	                if (headCheckpoint.maxSeqNum() > this.seqNum) {
325	                    this.seqNum = headCheckpoint.maxSeqNum();
326	                }
327	
328	                newCheckpointedHeadpage(headCheckpoint.getPageNum() + 1);
329	
330	                pqSizeBytes += (long) pageIO.getHead();
331	                ensureDiskAvailable(this.maxBytes, pqSizeBytes);
332	                return true;
333	            }
334	        }
335	        return false;
336	    }
