338	    /**
339	     * delete files for the given page
340	     *
341	     * @param checkpoint the tail page {@link Checkpoint}
342	     * @param pageIO the tail page {@link PageIO}
343	     * @throws IOException
344	     */
345	    private void purgeTailPage(Checkpoint checkpoint, PageIO pageIO) throws IOException {
346	        try {
347	            pageIO.purge();
348	        } catch (NoSuchFileException e) { /* ignore */ }
349	
350	        // we want to keep all the "middle" checkpoints between the first unacked tail page and the head page
351	        // to always have a contiguous sequence of checkpoints which helps figuring queue integrity. for this
352	        // we will remove any prepended fully acked tail pages but keep all other checkpoints between the first
353	        // unacked tail page and the head page. we did however purge the data file to free disk resources.
354	
355	        if (this.tailPages.size() == 0) {
356	            // this is the first tail page and it is fully acked so just purge it
357	            this.checkpointIO.purge(this.checkpointIO.tailFileName(checkpoint.getPageNum()));
358	        }
359	    }
