361	    /**
362	     * add a not fully-acked tail page into this queue structures and un-mmap it.
363	     *
364	     * @param page the tail {@link Page}
365	     * @throws IOException
366	     */
367	    private void addTailPage(Page page) throws IOException {
368	        this.tailPages.add(page);
369	        this.unreadTailPages.add(page);
370	        this.unreadCount += page.unreadCount();
371	
372	        // for now deactivate all tail pages, we will only reactivate the first one at the end
373	        page.getPageIO().deactivate();
374	    }
