33	import org.apache.logging.log4j.Logger;
34	import org.logstash.ackedqueue.Checkpoint;
35	
36	
37	/**
38	* File implementation for {@link CheckpointIO}
39	* */
40	public class FileCheckpointIO implements CheckpointIO {
41	//    Checkpoint file structure
42	//
43	//    byte version;
44	//    int pageNum;
45	//    int firstUnackedPageNum;
46	//    long firstUnackedSeqNum;
47	//    long minSeqNum;
48	//    int elementCount;
49	
50	private static final Logger logger = LogManager.getLogger(FileCheckpointIO.class);
51	
52	public static final int BUFFER_SIZE = Short.BYTES // version
53	+ Integer.BYTES  // pageNum
54	+ Integer.BYTES  // firstUnackedPageNum
55	+ Long.BYTES     // firstUnackedSeqNum
56	+ Long.BYTES     // minSeqNum
57	+ Integer.BYTES  // eventCount
58	+ Integer.BYTES;    // checksum
59	
60	/**
61	* Using {@link java.nio.DirectByteBuffer} to avoid allocations and copying in
62	* {@link FileChannel#write(ByteBuffer)} and {@link CRC32#update(ByteBuffer)} calls.
63	*/
64	private final ByteBuffer buffer = ByteBuffer.allocateDirect(BUFFER_SIZE);
65	
66	private final CRC32 crc32 = new CRC32();
67	
68	private final boolean retry;
69	
70	private static final String HEAD_CHECKPOINT = "checkpoint.head";
71	private static final String TAIL_CHECKPOINT = "checkpoint.";
72	private final Path dirPath;
73	
74	public FileCheckpointIO(Path dirPath) {
75	this(dirPath, false);
76	}
77	
78	public FileCheckpointIO(Path dirPath, boolean retry) {
79	this.dirPath = dirPath;
80	this.retry = retry;
81	}
82	
83	@Override
84	public Checkpoint read(String fileName) throws IOException {
85	return read(
86	ByteBuffer.wrap(Files.readAllBytes(dirPath.resolve(fileName)))
87	);
88	}
89	
90	@Override
91	public Checkpoint write(String fileName, int pageNum, int firstUnackedPageNum, long firstUnackedSeqNum, long minSeqNum, int elementCount) throws IOException {
92	Checkpoint checkpoint = new Checkpoint(pageNum, firstUnackedPageNum, firstUnackedSeqNum, minSeqNum, elementCount);
93	write(fileName, checkpoint);
94	return checkpoint;
95	}
96	
97	@Override
98	public void write(String fileName, Checkpoint checkpoint) throws IOException {
99	write(checkpoint, buffer);
100	buffer.flip();
101	final Path tmpPath = dirPath.resolve(fileName + ".tmp");
102	try (FileOutputStream out = new FileOutputStream(tmpPath.toFile())) {
103	out.getChannel().write(buffer);
104	out.getFD().sync();
105	}
106	
107	try {
108	Files.move(tmpPath, dirPath.resolve(fileName), StandardCopyOption.ATOMIC_MOVE);
109	} catch (IOException ex) {
110	if (retry) {
111	try {
112	logger.error("Retrying after exception writing checkpoint: " + ex);
113	Thread.sleep(500);
114	Files.move(tmpPath, dirPath.resolve(fileName), StandardCopyOption.ATOMIC_MOVE);
115	} catch (IOException | InterruptedException ex2) {
116	logger.error("Aborting after second exception writing checkpoint: " + ex2);
117	throw ex;
118	}
119	} else {
120	logger.error("Error writing checkpoint: " + ex);
121	throw ex;
122	}
123	}
124	}
125	
126	@Override
127	public void purge(String fileName) throws IOException {
128	Path path = dirPath.resolve(fileName);
129	Files.delete(path);
130	}
