141	return TAIL_CHECKPOINT + pageNum;
142	}
143	
144	public static Checkpoint read(ByteBuffer data) throws IOException {
145	int version = (int) data.getShort();
146	// TODO - build reader for this version
147	int pageNum = data.getInt();
148	int firstUnackedPageNum = data.getInt();
149	long firstUnackedSeqNum = data.getLong();
150	long minSeqNum = data.getLong();
151	int elementCount = data.getInt();
152	final CRC32 crc32 = new CRC32();
153	crc32.update(data.array(), 0, BUFFER_SIZE - Integer.BYTES);
154	int calcCrc32 = (int) crc32.getValue();
155	int readCrc32 = data.getInt();
156	if (readCrc32 != calcCrc32) {
157	throw new IOException(String.format("Checkpoint checksum mismatch, expected: %d, actual: %d", calcCrc32, readCrc32));
158	}
159	if (version != Checkpoint.VERSION) {
160	throw new IOException("Unknown file format version: " + version);
161	}
162	
163	return new Checkpoint(pageNum, firstUnackedPageNum, firstUnackedSeqNum, minSeqNum, elementCount);
164	}
165	
166	private void write(Checkpoint checkpoint, ByteBuffer buf) {
167	crc32.reset();
168	buf.clear();
169	buf.putShort((short)Checkpoint.VERSION);
170	buf.putInt(checkpoint.getPageNum());
171	buf.putInt(checkpoint.getFirstUnackedPageNum());
172	buf.putLong(checkpoint.getFirstUnackedSeqNum());
173	buf.putLong(checkpoint.getMinSeqNum());
174	buf.putInt(checkpoint.getElementCount());
175	buf.flip();
176	crc32.update(buf);
177	buf.position(BUFFER_SIZE - Integer.BYTES).limit(BUFFER_SIZE);
178	buf.putInt((int)crc32.getValue());
179	}
180	}
