174	if ((oldBuffer == null) || buffer.length > oldBuffer.length) {
175	// Could use CAS, but should not really matter
176	_byteBuffers.set(ix, buffer);
177	}
178	}
179	
180	/*
181	/**********************************************************
182	/* Public API, char buffers
183	/**********************************************************
184	*/
185	
186	public final char[] allocCharBuffer(int ix) {
187	return allocCharBuffer(ix, 0);
188	}
189	
190	public char[] allocCharBuffer(int ix, int minSize) {
191	final int DEF_SIZE = charBufferLength(ix);
192	if (minSize < DEF_SIZE) {
193	minSize = DEF_SIZE;
194	}
195	char[] buffer = _charBuffers.getAndSet(ix, null);
196	if (buffer == null || buffer.length < minSize) {
197	buffer = calloc(minSize);
198	}
199	return buffer;
200	}
201	
202	public void releaseCharBuffer(int ix, char[] buffer) {
203	// 13-Jan-2024, tatu: [core#1186] Replace only if beneficial:
204	char[] oldBuffer = _charBuffers.get(ix);
205	if ((oldBuffer == null) || buffer.length > oldBuffer.length) {
206	// Could use CAS, but should not really matter
207	_charBuffers.set(ix, buffer);
208	}
209	}
210	
211	/*
212	/**********************************************************
213	/* Overridable helper methods
214	/**********************************************************
215	*/
216	
217	protected int byteBufferLength(int ix) {
218	return BYTE_BUFFER_LENGTHS[ix];
219	}
220	
221	protected int charBufferLength(int ix) {
222	return CHAR_BUFFER_LENGTHS[ix];
223	}
224	
225	/*
226	/**********************************************************
227	/* Actual allocations separated for easier debugging/profiling
228	/**********************************************************
229	*/
230	
231	protected byte[] balloc(int size) { return new byte[size]; }
232	protected char[] calloc(int size) { return new char[size]; }
233	
234	/*
235	/**********************************************************
236	/* WithPool implementation
237	/**********************************************************
238	*/
239	
240	/**
241	* Method called by owner of this recycler instance, to provide reference to
242	* {@link RecyclerPool} into which instance is to be released (if any)
243	*
244	* @since 2.16
245	*/
246	@Override
247	public BufferRecycler withPool(RecyclerPool<BufferRecycler> pool) {
248	if (_pool != null) {
249	throw new IllegalStateException("BufferRecycler already linked to pool: "+pool);
250	}
251	// assign to pool to which this BufferRecycler belongs in order to release it
252	// to the same pool when the work will be completed
253	_pool = Objects.requireNonNull(pool);
254	return this;
255	}
256	
257	/**
258	* Method called when owner of this recycler no longer wishes use it; this should
259	* return it to pool passed via {@code withPool()} (if any).
260	*
261	* @since 2.16
262	*/
263	@Override
264	public void releaseToPool() {
265	if (_pool != null) {
266	RecyclerPool<BufferRecycler> tmpPool = _pool;
267	// nullify the reference to the pool in order to avoid the risk of releasing
268	// the same BufferRecycler more than once, thus compromising the pool integrity
269	_pool = null;
270	tmpPool.releasePooled(this);
271	}
272	}
