10	/**
11	* API for object pools that control creation and possible reuse of
12	* objects that are costly to create (often things like encoding/decoding buffers).
13	*<p>
14	* Also contains partial (base) implementations for pools that use different
15	* strategies on retaining objects for reuse.
16	* Following implementations are included:
17	*<ul>
18	* <li>{@link NonRecyclingPoolBase} which does not retain or recycle anything and
19	* will always simply construct and return new instance when
20	* {@code acquireBufferRecycler} is called
21	*  </li>
22	* <li>{@link ThreadLocalPoolBase} which uses {@link ThreadLocal} to retain at most
23	*   1 object per {@link Thread}.
24	* </li>
25	* <li>{@link BoundedPoolBase} is "bounded pool" and retains at most N objects (default value being
26	*  {@link BoundedPoolBase#DEFAULT_CAPACITY}) at any given time.
27	*  </li>
28	* <li>Two implementations -- {@link ConcurrentDequePoolBase}, {@link LockFreePoolBase}
29	*   -- are "unbounded" and retain any number of objects released: in practice
30	*   it is at most the highest number of concurrently used {@link BufferRecycler}s.
31	*  </li>
32	*</ul>
33	*
34	*<p>
35	* Default implementations are also included as nested classes.
36	*
37	* @param <P> Type of Objects pool recycles
38	*
39	* @since 2.16
40	*/
41	public interface RecyclerPool<P extends RecyclerPool.WithPool<P>> extends Serializable
42	{
43	/**
44	* Simple add-on interface that poolable entities must implement.
45	*
46	* @param <P> Self type
47	*/
48	public interface WithPool<P extends WithPool<P>> {
49	/**
50	* Method to call to add link from pooled item back to pool
51	* that handles it
52	* 
53	* @param pool Pool that "owns" pooled item
54	*
55	* @return This item (for call chaining)
56	*/
57	P withPool(RecyclerPool<P> pool);
58	
59	/**
60	* Method called when this item is to be released back to the
61	* pool that owns it (if any)
62	*/
63	void releaseToPool();
64	}
65	
66	/**
67	* Method called to acquire a Pooled value from this pool
68	* AND make sure it is linked back to this
69	* {@link RecyclerPool} as necessary for it to be
70	* released (see {@link #releasePooled}) later after usage ends.
71	* Actual acquisition is done by a call to {@link #acquirePooled()}.
72	*<p>
73	* Default implementation calls {@link #acquirePooled()} followed by
74	* a call to {@link WithPool#withPool}.
75	*
76	* @return Pooled instance for caller to use; caller expected
77	*   to call {@link #releasePooled} after it is done using instance.
78	*/
79	default P acquireAndLinkPooled() {
80	return acquirePooled().withPool(this);
81	}
82	
83	/**
84	* Method for sub-classes to implement for actual acquire logic; called
85	* by {@link #acquireAndLinkPooled()}.
86	*
87	* @return Instance acquired (pooled or just constructed)
88	*/
89	P acquirePooled();
90	
91	/**
92	* Method that should be called when previously acquired (see {@link #acquireAndLinkPooled})
93	* pooled value that is no longer needed; this lets pool to take ownership
94	* for possible reuse.
95	*
96	* @param pooled Pooled instance to release back to pool
97	*/
98	void releasePooled(P pooled);
99	
100	/**
101	* Optional method that may allow dropping of all pooled Objects; mostly
102	* useful for unbounded pool implementations that may retain significant
103	* memory and that may then be cleared regularly.
104	*
105	* @since 2.17
106	*
107	* @return {@code true} If pool supports operation and dropped all pooled
108	*    Objects; {@code false} otherwise.
109	*/
110	default boolean clear() {
111	return false;
112	}
113	
114	/*
115	/**********************************************************************
116	/* Partial/base RecyclerPool implementations
117	/**********************************************************************
118	*/
119	
120	/**
121	* Default {@link RecyclerPool} implementation that uses
122	* {@link ThreadLocal} for recycling instances. 
123	* Instances are stored using {@link java.lang.ref.SoftReference}s so that
124	* they may be Garbage Collected as needed by JVM.
125	*<p>
126	* Note that this implementation may not work well on platforms where
127	* {@link java.lang.ref.SoftReference}s are not well supported (like
128	* Android), or on platforms where {@link java.lang.Thread}s are not
129	* long-living or reused (like Project Loom).
130	*/
131	abstract class ThreadLocalPoolBase<P extends WithPool<P>> implements RecyclerPool<P>
132	{
133	private static final long serialVersionUID = 1L;
134	
135	protected ThreadLocalPoolBase() { }
136	
137	// // // Actual API implementation
138	
139	@Override
140	public P acquireAndLinkPooled() {
141	// since this pool doesn't do anything on release it doesn't need to be registered on the BufferRecycler
142	return acquirePooled();
143	}
144	
145	@Override
146	public abstract P acquirePooled();
147	
148	@Override
149	public void releasePooled(P pooled) {
150	// nothing to do, relies on ThreadLocal
151	}
152	
153	// Due to use of ThreadLocal no tracking available; cannot clear
154	@Override
155	public boolean clear() {
156	return false;
157	}
158	}
159	
160	/**
161	* {@link RecyclerPool} implementation that does not use
162	* any pool but simply creates new instances when necessary.
163	*/
164	abstract class NonRecyclingPoolBase<P extends WithPool<P>> implements RecyclerPool<P>
165	{
166	private static final long serialVersionUID = 1L;
167	
168	// // // Actual API implementation
169	
170	@Override
171	public P acquireAndLinkPooled() {
172	// since this pool doesn't do anything on release it doesn't need to be registered on the BufferRecycler
173	return acquirePooled();
174	}
175	
176	@Override
177	public abstract P acquirePooled();
178	
179	@Override
180	public void releasePooled(P pooled) {
181	// nothing to do, there is no underlying pool
182	}
183	
184	/**
185	* Although no pooling occurs, we consider clearing to succeed,
186	* so returns always {@code true}.
187	*
188	* @return Always returns {@code true}
189	*/
190	@Override
191	public boolean clear() {
192	return true;
193	}
194	}
195	
196	/**
197	* Intermediate base class for instances that are stateful and require
198	* special handling with respect to JDK serialization, to retain
199	* "global" reference distinct from non-shared ones.
200	*/
201	abstract class StatefulImplBase<P extends WithPool<P>>
202	implements RecyclerPool<P>
203	{
204	private static final long serialVersionUID = 1L;
205	
206	public final static int SERIALIZATION_SHARED = -1;
207	
208	public final static int SERIALIZATION_NON_SHARED = 1;
209	
210	/**
211	* Value that indicates basic aspects of pool for JDK serialization;
212	* either marker for shared/non-shared, or possibly bounded size;
213	* depends on sub-class.
214	*/
215	protected final int _serialization;
216	
217	protected StatefulImplBase(int serialization) {
218	_serialization = serialization;
219	}
220	
221	protected Optional<StatefulImplBase<P>> _resolveToShared(StatefulImplBase<P> shared) {
222	if (_serialization == SERIALIZATION_SHARED) {
223	return Optional.of(shared);
224	}
225	return Optional.empty();
226	}
227	
228	public abstract P createPooled();
229	}
230	
231	/**
232	* {@link RecyclerPool} implementation that uses
233	* {@link ConcurrentLinkedDeque} for recycling instances.
234	*<p>
235	* Pool is unbounded: see {@link RecyclerPool} what this means.
236	*/
237	abstract class ConcurrentDequePoolBase<P extends WithPool<P>>
238	extends StatefulImplBase<P>
239	{
240	private static final long serialVersionUID = 1L;
241	
242	protected final transient Deque<P> pool;
243	
244	protected ConcurrentDequePoolBase(int serialization) {
245	super(serialization);
246	pool = new ConcurrentLinkedDeque<>();
247	}
248	
249	// // // Actual API implementation
250	
251	@Override
252	public P acquirePooled() {
253	P pooled = pool.pollFirst();
254	if (pooled == null) {
255	pooled = createPooled();
256	}
257	return pooled;
258	}
259	
260	@Override
261	public void releasePooled(P pooled) {
262	pool.offerLast(pooled);
263	}
264	
265	@Override
266	public boolean clear() {
267	pool.clear();
268	return true;
269	}
270	}
271	
272	/**
273	* {@link RecyclerPool} implementation that uses
274	* a lock free linked list for recycling instances.
275	* Pool is unbounded: see {@link RecyclerPool} for
276	* details on what this means.
277	*/
278	abstract class LockFreePoolBase<P extends WithPool<P>>
279	extends StatefulImplBase<P>
280	{
281	private static final long serialVersionUID = 1L;
282	
283	// Needs to be transient to avoid JDK serialization from writing it out
284	private final transient AtomicReference<Node<P>> head;
285	
286	// // // Life-cycle (constructors, factory methods)
287	
288	protected LockFreePoolBase(int serialization) {
289	super(serialization);
290	head = new AtomicReference<>();
291	}
292	
293	// // // Actual API implementation
294	
295	@Override
296	public P acquirePooled() {
297	// This simple lock free algorithm uses an optimistic compareAndSet strategy to
298	// populate the underlying linked list in a thread-safe way. However, under very
299	// heavy contention, the compareAndSet could fail multiple times, so it seems a
300	// reasonable heuristic to limit the number of retries in this situation.
301	for (int i = 0; i < 3; i++) {
302	Node<P> currentHead = head.get();
303	if (currentHead == null) {
304	return createPooled();
305	}
306	if (head.compareAndSet(currentHead, currentHead.next)) {
307	currentHead.next = null;
308	return currentHead.value;
309	}
310	}
311	return createPooled();
312	}
313	
314	@Override
315	public void releasePooled(P pooled) {
316	Node<P> newHead = new Node<>(pooled);
317	for (int i = 0; i < 3; i++) {
318	newHead.next = head.get();
319	if (head.compareAndSet(newHead.next, newHead)) {
320	return;
321	}
322	}
323	}
324	
325	protected static class Node<P> {
326	final P value;
327	Node<P> next;
328	
329	Node(P value) {
330	this.value = value;
331	}
332	}
333	
334	// Yes, we can clear it
335	@Override
336	public boolean clear() {
337	head.set(null);
338	return true;
339	}
340	}
341	
342	/**
343	* {@link RecyclerPool} implementation that uses
344	* a bounded queue ({@link ArrayBlockingQueue} for recycling instances.
345	* This is "bounded" pool since it will never hold on to more
346	* pooled instances than its size configuration:
347	* the default size is {@link BoundedPoolBase#DEFAULT_CAPACITY}.
348	*/
349	abstract class BoundedPoolBase<P extends WithPool<P>>
350	extends StatefulImplBase<P>
351	{
352	private static final long serialVersionUID = 1L;
353	
354	/**
355	* Default capacity which limits number of items that are ever
356	* retained for reuse.
357	*/
358	public final static int DEFAULT_CAPACITY = 100;
359	
360	private final transient ArrayBlockingQueue<P> pool;
361	
362	private final transient int capacity;
363	
364	// // // Life-cycle (constructors, factory methods)
365	
366	protected BoundedPoolBase(int capacityAsId) {
367	super(capacityAsId);
368	capacity = (capacityAsId <= 0) ? DEFAULT_CAPACITY : capacityAsId;
369	pool = new ArrayBlockingQueue<>(capacity);
370	}
371	
372	// // // Actual API implementation
373	
374	@Override
375	public P acquirePooled() {
376	P pooled = pool.poll();
377	if (pooled == null) {
378	pooled = createPooled();
379	}
380	return pooled;
381	}
382	
383	@Override
384	public void releasePooled(P pooled) {
385	pool.offer(pooled);
386	}
387	
388	@Override
389	public boolean clear() {
390	pool.clear();
391	return true;
392	}
393	
