102	this.httpClient = httpClient;
103	}
104	
105	/**
106	* Makes the request to the endpoint.
107	*
108	* @return an object representing the response, or {@code null}
109	* @throws IOException for most I/O exceptions when making the request
110	* @throws RegistryException for known exceptions when interacting with the registry
111	*/
112	T call() throws IOException, RegistryException {
113	String apiRouteBase = "https://" + registryEndpointRequestProperties.getServerUrl() + "/v2/";
114	URL initialRequestUrl = registryEndpointProvider.getApiRoute(apiRouteBase);
115	return call(initialRequestUrl);
116	}
117	
118	/**
119	* Calls the registry endpoint with a certain {@link URL}.
120	*
121	* @param url the endpoint URL to call
122	* @return an object representing the response
123	* @throws IOException for most I/O exceptions when making the request
124	* @throws RegistryException for known exceptions when interacting with the registry
125	*/
126	private T call(URL url) throws IOException, RegistryException {
127	String serverUrl = registryEndpointRequestProperties.getServerUrl();
128	String imageName = registryEndpointRequestProperties.getImageName();
129	
130	Request.Builder requestBuilder =
131	Request.builder()
132	.setUserAgent(userAgent)
133	.setHttpTimeout(JibSystemProperties.getHttpTimeout())
134	.setAccept(registryEndpointProvider.getAccept())
135	.setBody(registryEndpointProvider.getContent())
136	.setAuthorization(authorization);
137	
138	try (Response response =
139	httpClient.call(registryEndpointProvider.getHttpMethod(), url, requestBuilder.build())) {
140	
141	return registryEndpointProvider.handleResponse(response);
142	
143	} catch (ResponseException ex) {
144	// First, see if the endpoint provider handles an exception as an expected response.
145	try {
146	return registryEndpointProvider.handleHttpResponseException(ex);
147	
148	} catch (ResponseException responseException) {
149	if (responseException.getStatusCode() == HttpStatusCodes.STATUS_CODE_BAD_REQUEST
150	|| responseException.getStatusCode() == HttpStatusCodes.STATUS_CODE_NOT_FOUND
151	|| responseException.getStatusCode()
152	== HttpStatusCodes.STATUS_CODE_METHOD_NOT_ALLOWED) {
153	// The name or reference was invalid.
154	throw newRegistryErrorException(responseException);
155	
156	} else if (responseException.getStatusCode() == HttpStatusCodes.STATUS_CODE_FORBIDDEN) {
157	throw new RegistryUnauthorizedException(serverUrl, imageName, responseException);
158	
159	} else if (responseException.getStatusCode() == HttpStatusCodes.STATUS_CODE_UNAUTHORIZED) {
160	if (responseException.requestAuthorizationCleared()) {
161	throw new RegistryCredentialsNotSentException(serverUrl, imageName);
162	} else {
163	// Credentials are either missing or wrong.
164	throw new RegistryUnauthorizedException(serverUrl, imageName, responseException);
165	}
166	
167	} else {
168	// Unknown
169	throw responseException;
170	}
171	}
172	
173	} catch (IOException ex) {
174	logError("I/O error for image [" + serverUrl + "/" + imageName + "]:");
175	logError("    " + ex.getClass().getName());
176	logError("    " + (ex.getMessage() == null ? "(null exception message)" : ex.getMessage()));
177	logErrorIfBrokenPipe(ex);
178	
179	if (ex instanceof SSLException) {
180	throw new InsecureRegistryException(url, ex);
181	}
182	throw ex;
183	}
184	}
