186	@VisibleForTesting
187	RegistryErrorException newRegistryErrorException(ResponseException responseException) {
188	RegistryErrorExceptionBuilder registryErrorExceptionBuilder =
189	new RegistryErrorExceptionBuilder(
190	registryEndpointProvider.getActionDescription(), responseException);
191	
192	try {
193	ErrorResponseTemplate errorResponse =
194	JsonTemplateMapper.readJson(responseException.getContent(), ErrorResponseTemplate.class);
195	for (ErrorEntryTemplate errorEntry : errorResponse.getErrors()) {
196	registryErrorExceptionBuilder.addReason(errorEntry);
197	}
198	} catch (IOException ex) {
199	registryErrorExceptionBuilder.addReason(
200	"registry returned error code "
201	+ responseException.getStatusCode()
202	+ "; possible causes include invalid or wrong reference. Actual error output follows:\n"
203	+ responseException.getContent()
204	+ "\n");
205	}
206	
207	return registryErrorExceptionBuilder.build();
208	}
