210	/** Logs error message in red. */
211	private void logError(String message) {
212	eventHandlers.dispatch(LogEvent.error("\u001B[31;1m" + message + "\u001B[0m"));
213	}
214	
215	private void logErrorIfBrokenPipe(IOException ex) {
216	if (isBrokenPipe(ex)) {
217	logError(
218	"broken pipe: the server shut down the connection. Check the server log if possible. "
219	+ "This could also be a proxy issue. For example, a proxy may prevent sending "
220	+ "packets that are too large.");
221	}
222	}
