76	if (rawType.equals(Object.class) && !returnTypeGenericMetadata.hasRawExtraInterfaces()) {
77	return null;
78	}
79	
80	return deepStub(invocation, returnTypeGenericMetadata);
81	}
82	
83	private Object deepStub(
84	InvocationOnMock invocation, GenericMetadataSupport returnTypeGenericMetadata)
85	throws Throwable {
86	InvocationContainerImpl container = MockUtil.getInvocationContainer(invocation.getMock());
87	
88	Answer existingAnswer = container.findStubbedAnswer();
89	if (existingAnswer != null) {
90	return existingAnswer.answer(invocation);
91	}
92	
93	// record deep stub answer
94	StubbedInvocationMatcher stubbing =
95	recordDeepStubAnswer(
96	newDeepStubMock(returnTypeGenericMetadata, invocation.getMock()),
97	container);
98	
99	// deep stubbing creates a stubbing and immediately uses it
100	// so the stubbing is actually used by the same invocation
101	stubbing.markStubUsed(stubbing.getInvocation());
102	
103	return stubbing.answer(invocation);
104	}
105	
106	/**
107	* Creates a mock using the Generics Metadata.
108	*
109	* <li>Finally as we want to mock the actual type, but we want to pass along the contextual generics meta-data
110	* that was resolved for the current return type, for this to happen we associate to the mock an new instance of
111	* {@link ReturnsDeepStubs} answer in which we will store the returned type generic metadata.
112	*
113	* @param returnTypeGenericMetadata The metadata to use to create the new mock.
114	* @param parentMock                The parent of the current deep stub mock.
115	* @return The mock
116	*/
117	private Object newDeepStubMock(
118	GenericMetadataSupport returnTypeGenericMetadata, Object parentMock) {
119	MockCreationSettings parentMockSettings = MockUtil.getMockSettings(parentMock);
120	return mockitoCore()
121	.mock(
122	returnTypeGenericMetadata.rawType(),
123	withSettingsUsing(returnTypeGenericMetadata, parentMockSettings));
124	}
125	
126	private MockSettings withSettingsUsing(
127	GenericMetadataSupport returnTypeGenericMetadata,
128	MockCreationSettings<?> parentMockSettings) {
129	MockSettings mockSettings =
130	returnTypeGenericMetadata.hasRawExtraInterfaces()
131	? withSettings()
132	.extraInterfaces(returnTypeGenericMetadata.rawExtraInterfaces())
133	: withSettings();
134	
135	return propagateSerializationSettings(mockSettings, parentMockSettings)
136	.defaultAnswer(returnsDeepStubsAnswerUsing(returnTypeGenericMetadata))
137	.mockMaker(parentMockSettings.getMockMaker());
138	}
139	
140	private MockSettings propagateSerializationSettings(
141	MockSettings mockSettings, MockCreationSettings parentMockSettings) {
142	return mockSettings.serializable(parentMockSettings.getSerializableMode());
143	}
144	
145	private ReturnsDeepStubs returnsDeepStubsAnswerUsing(
146	final GenericMetadataSupport returnTypeGenericMetadata) {
147	return new ReturnsDeepStubsSerializationFallback(returnTypeGenericMetadata);
148	}
149	
150	private StubbedInvocationMatcher recordDeepStubAnswer(
151	final Object mock, InvocationContainerImpl container) {
152	DeeplyStubbedAnswer answer = new DeeplyStubbedAnswer(mock);
153	return container.addAnswer(answer, false, null);
154	}
155	
156	protected GenericMetadataSupport actualParameterizedType(Object mock) {
157	CreationSettings mockSettings =
158	(CreationSettings) MockUtil.getMockHandler(mock).getMockSettings();
159	return GenericMetadataSupport.inferFrom(mockSettings.getTypeToMock());
160	}
161	
162	private static class ReturnsDeepStubsSerializationFallback extends ReturnsDeepStubs
163	implements Serializable {
164	@SuppressWarnings("serial") // not gonna be serialized
165	private final GenericMetadataSupport returnTypeGenericMetadata;
166	
167	public ReturnsDeepStubsSerializationFallback(
168	GenericMetadataSupport returnTypeGenericMetadata) {
169	this.returnTypeGenericMetadata = returnTypeGenericMetadata;
170	}
171	
172	@Override
173	protected GenericMetadataSupport actualParameterizedType(Object mock) {
174	return returnTypeGenericMetadata;
175	}
176	
177	/**
178	* Generics support and serialization with deep stubs don't work together.
179	* <p>
180	* The issue is that GenericMetadataSupport is not serializable because
181	* the type elements inferred via reflection are not serializable. Supporting
182	* serialization would require to replace all types coming from the Java reflection
183	* with our own and still managing type equality with the JDK ones.
184	*/
185	private Object writeReplace() throws IOException {
186	return Mockito.RETURNS_DEEP_STUBS;
187	}
188	}
189	
190	private static class DeeplyStubbedAnswer implements Answer<Object>, Serializable {
191	@SuppressWarnings(
192	"serial") // serialization will fail with a nice message if mock not serializable
193	private final Object mock;
194	
195	DeeplyStubbedAnswer(Object mock) {
196	this.mock = mock;
197	}
198	
199	@Override
200	public Object answer(InvocationOnMock invocation) throws Throwable {
201	return mock;
202	}
203	}
204	
205	private static MockitoCore mockitoCore() {
206	return LazyHolder.MOCKITO_CORE;
207	}
208	
209	private static ReturnsEmptyValues delegate() {
210	return LazyHolder.DELEGATE;
211	}
212	
213	private static class LazyHolder {
214	private static final MockitoCore MOCKITO_CORE = new MockitoCore();
215	private static final ReturnsEmptyValues DELEGATE = new ReturnsEmptyValues();
216	}
217	}
