39	public static MockMaker getMockMaker(String mockMaker) {
40	if (mockMaker == null) {
41	return defaultMockMaker;
42	}
43	
44	String typeName;
45	if (DefaultMockitoPlugins.MOCK_MAKER_ALIASES.contains(mockMaker)) {
