51	Class<? extends MockMaker> type;
52	// Using the context class loader because PluginInitializer.loadImpl is using it as well.
53	// Personally, I am suspicious whether the context class loader is a good choice in either
54	// of these cases.
55	ClassLoader loader = Thread.currentThread().getContextClassLoader();
56	if (loader == null) {
57	loader = ClassLoader.getSystemClassLoader();
58	}
59	try {
60	type = loader.loadClass(typeName).asSubclass(MockMaker.class);
61	} catch (Exception e) {
62	throw new IllegalStateException("Failed to load MockMaker: " + mockMaker, e);
63	}
64	
65	return mockMakers.computeIfAbsent(
66	type,
67	t -> {
68	try {
69	return t.getDeclaredConstructor().newInstance();
70	} catch (Exception e) {
71	throw new IllegalStateException(
72	"Failed to construct MockMaker: " + t.getName(), e);
73	}
