86	
87	T mock;
88	if (spiedInstance != null) {
89	mock =
90	mockMaker
91	.createSpy(settings, mockHandler, (T) spiedInstance)
92	.orElseGet(
93	() -> {
94	T instance = mockMaker.createMock(settings, mockHandler);
95	new LenientCopyTool().copyToMock(spiedInstance, instance);
96	return instance;
97	});
98	} else {
99	mock = mockMaker.createMock(settings, mockHandler);
100	}
101	
102	return mock;
103	}
