132	public static boolean isMock(Object mock) {
133	// TODO SF (perf tweak) in our codebase we call mockMaker.getHandler() multiple times
134	// unnecessarily
135	// This is not ideal because getHandler() can be expensive (reflective calls inside mock
136	// maker)
137	// The frequent pattern in the codebase are separate calls to: 1) isMock(mock) then 2)
138	// getMockHandler(mock)
139	// We could replace it with using mockingDetails().isMock()
140	// Let's refactor the codebase and use new mockingDetails() in all relevant places.
141	// Potentially we could also move other methods to MockitoMock, some other candidates:
142	// getInvocationContainer, isSpy, etc.
143	// This also allows us to reuse our public API MockingDetails
144	if (mock == null) {
145	return false;
146	}
147	return getMockHandlerOrNull(mock) != null;
148	}
149	
150	private static MockHandler<?> getMockHandlerOrNull(Object mock) {
151	if (mock == null) {
152	throw new NotAMockException("Argument should be a mock, but is null!");
153	}
154	
155	mock = resolve(mock);
156	
157	for (MockMaker mockMaker : mockMakers.values()) {
158	MockHandler<?> handler = mockMaker.getHandler(mock);
159	if (handler != null) {
160	assert getMockMaker(handler.getMockSettings().getMockMaker()) == mockMaker;
161	return handler;
162	}
163	}
164	return null;
165	}
